INSERT INTO engine_bug_queue (bug_class, title, severity, owner_cluster, root_cause, prevention_rule, probe_type, probe_logic, status, concepts_affected, fixed_in_files, discovered_in_session, row_type, fixed_at) VALUES
('vg_readout_norm_bars_merge_to_one_stroke_in_the_readout_font_stack', 'The readout panel’s serif stack has no usable U+2016, so ‖d₁×d₂‖ rendered as |d₁×d₂| beside a formula surface drawing it correctly', 'MODERATE', 'peter_parker:field3d_surgeon', 'Filed by the 2026-08-10 eye-walk as a wrong LABEL STRING (HUD "|d₁×d₂| = 0.936" under a formula surface writing ‖d₁×d₂‖); the dispatch REFUTED the premise — VG_READOUT_LABEL.cross_norm has been "‖d₁×d₂‖" (real U+2016) since the VG-C build, and git log --all -S shows a single-bar literal NEVER existed in the tree. The defect is the GLYPH: the #vg_readout cssText ended "Cambria Math",Georgia,serif, and neither Georgia nor the serif default ships a usable DOUBLE VERTICAL LINE — measured in THE EYE’s own Chromium, ‖ advances 3.65px under the serif stack (both strokes collapsing to one 2px stem at 13px) vs 7.80px under monospace, the generic #formula_overlay itself uses. S9’s "correct" ‖n‖ was the identical merge on a narrower letter — the eye-walk’s own control case was wrong. Fixed by ONE WORD: the panel’s last-resort family becomes monospace, so both surfaces of one screen resolve the norm bar through the same font; per-character fallback proven to move exactly one glyph (every other character byte-identical under both stacks). The products half’s |a|, |b|, |a×b| are that concept’s own consistent school magnitude notation and were deliberately NOT rewritten — doing so would plant this bug_class mirrored. RESIDUAL RISK, untestable on this machine: a client with Cambria Math actually installed resolves ‖ through Cambria Math instead; as a math font its norm delimiter should be properly spaced, but it was not measurable here. RE-BASELINE NOTE: every #9 frame printing n_norm/cross_norm changes pixels — H2 re-baseline after founder OK (Rule 34e), chapter desk.', 'A glyph the design depends on is verified in the FONT STACK that has to draw it, at the size it draws at — a correct string in a font without the glyph is the same defect as a wrong string, and invisible to every source-level check. When a label looks wrong on pixels, diff the STRING first (git log -S), then the RENDER: the two have different owners and different fixes. Distinct surfaces showing one quantity resolve its critical glyphs through the same font family.', 'js_eval', 'Gate §26: render cross_norm/n_norm through the shipped vgReadoutLine and assert exactly two U+2016 and zero U+007C beside the vector name; parse the shipped #vg_readout cssText and assert its last-resort family is monospace and matches #formula_overlay’s generic; table-wide bar audit — every token classified scalar/vector, single bars never wrap a vector in the lines/planes half, the products-half allowlist byte-locked. Negative controls (both executed, anchor-guarded): a planted single-bar label table, and the genuine pre-fix serif cssText.', 'FIXED', ARRAY['lines_and_planes_in_space']::text[], ARRAY['src/lib/renderers/field_3d_renderer.ts', 'src/scripts/check_vector_geometry_3d.ts']::text[], 'session_2026-08-10_lines_and_planes_fix_round', 'incident', '2026-08-10T12:17:59.000Z')
